#include <algorithm>
#include <functional>
#include <iostream>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using R=vector<int>;using ll=long long;void need(bool b,const char*s){if(!b)throw runtime_error(s);}bool arc(R const&r,int i,int j){return r[i]>>j&1;}
vector<vector<int>> aut(R const&r){int n=r.size();vector<int>f(n,-1),used(n);vector<vector<int>>out;function<void(int)>go=[&](int a){if(a==n){out.push_back(f);return;}for(int b=0;b<n;b++)if(!used[b]&&__builtin_popcount((unsigned)r[a])==__builtin_popcount((unsigned)r[b])){bool ok=true;for(int k=0;k<a;k++)if(arc(r,a,k)!=arc(r,b,f[k])){ok=false;break;}if(ok){f[a]=b;used[b]=1;go(a+1);used[b]=0;}}};go(0);return out;}
ll H(R const&r){int n=r.size(),N=1<<n;vector<vector<ll>>d(N,vector<ll>(n));for(int v=0;v<n;v++)d[1<<v][v]=1;for(int M=1;M<N;M++)for(int v=0;v<n;v++)if(d[M][v])for(int z=r[v]&~M;z;z&=z-1){int b=z&-z;d[M|b][__builtin_ctz((unsigned)b)]+=d[M][v];}return accumulate(d.back().begin(),d.back().end(),0LL);}
int main(){int graphs=0;ll totalH=0,totalF=0,halves=0;for(int n=3;n<=14;n++){ll fibers=0,classes=0,roots=0,convorbits=0,fixedclasses=0,mass3=0;set<R>allnormal;for(int d=0;2*d<=n-3;d++){int l=n-2-2*d;R r(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){bool f=!(i==d&&j==d+l+1);r[f?i:j]|=1<<(f?j:i);}auto group=aut(r);need(group.size()==(l==1?3u:1u),"Aut size");int central=0;for(auto const&f:group){bool yes=true;for(int i=0;i<n;i++)yes&=f[n-1-i]==n-1-f[i];central+=yes;}need(central==1,"centralizer");int half=n/2;vector<int>p;set<R>normal;ll count=0;function<void(int)>go=[&](int used){if((int)p.size()==half){halves++;vector<int>w=p;if(n%2)w.push_back(half);for(int i=half-1;i>=0;i--)w.push_back(n-1-p[i]);for(int i=1;i<n;i++)if(!arc(r,w[i-1],w[i]))return;count++;R a(n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(arc(r,w[i],w[j]))a[i]|=1<<j;need(normal.insert(a).second,"centralizer one gives unique normalization");for(int i=0;i<n-1;i++)need(arc(a,i,i+1),"Hamilton normalized");for(int i=0;i<n;i++)for(int j=0;j<n;j++)need(arc(a,i,j)==arc(a,n-1-j,n-1-i),"normalized converse");return;}for(int k=0;k<half;k++)if(!(used>>k&1))for(int x:{k,n-1-k})if(p.empty()||arc(r,p.back(),x)){p.push_back(x);go(used|1<<k);p.pop_back();}};go(0);ll expected=l%2?1:(1LL<<(l/2))+1;need(count==expected,"independent halfword count");ll h=H(r);need(h==(1LL<<l)+1,"independent full H");for(auto const&a:normal)need(allnormal.insert(a).second,"different classes have disjoint normalized graphs");
vector<int>eligible;if(l==1)eligible={d,d+1,d+2};else for(int x=d+1;x<=d+l;x++)eligible.push_back(x);set<set<int>>aorb,corb;for(int x:eligible){set<int>A,C;for(auto const&f:group){A.insert(f[x]);C.insert(f[x]);C.insert(n-1-f[x]);}aorb.insert(A);corb.insert(C);}int fix=0;for(auto const&A:aorb){set<int>B;for(int x:A)B.insert(n-1-x);fix+=A==B;}need(aorb.size()==l&&corb.size()==(l+1)/2&&fix==l%2,"root orbit formulas");classes++;roots+=aorb.size();convorbits+=corb.size();fixedclasses+=fix;mass3+=3/group.size();fibers+=count;graphs++;totalH+=h;totalF+=count;}
int s=n/2;need(classes==(n-1)/2&&roots==(n-1)*(n-1)/4,"class sums");need(fibers==(n%2?s:(1LL<<s)+s-3)&&allnormal.size()==(size_t)fibers,"normalization sum");need(mass3==3*classes-2*(n%2),"mass sum");need(2*convorbits==roots+fixedclasses,"Burnside converse");cout<<"ORDER "<<n<<" classes "<<classes<<" roots "<<roots<<" normalized "<<fibers<<"\n";}cout<<"PASS graphs "<<graphs<<" independent_H_sum "<<totalH<<" fixed_halfwords "<<totalF<<" halfpath_candidates "<<halves<<'\n';}
